\begin{align*} 10 \cdot 5 &= (1^2+3^2)(1^2+2^2) &&: 4 \cdot 4 = 16\\ 10 \cdot 5 &= 10 \cdot (1^2+2^2) &&: 2 \cdot 4 = 8\\ 10 \cdot 5 &= (1^2+3^2) \cdot 5 &&: 4 \cdot 2 = 8\\ 10 \cdot 5 &= 10 \cdot 5 &&: 2 \cdot 2 = 4\\ \end{align*}
